-- V15: governed runbook registry, instances, steps and audit ledger.
create table if not exists public.automation_runbooks(
 id uuid primary key default gen_random_uuid(),runbook_key text not null,version integer not null check(version>0),name text not null,
 category text not null check(category in ('operations','inventory','service','commercial','customer','system')),
 min_severity text not null default 'warning' check(min_severity in ('info','warning','high','critical')),
 risk_class text not null default 'advisory' check(risk_class in ('advisory','controlled','high_impact')),
 requires_action_approval boolean not null default false,max_duration_hours integer not null default 48 check(max_duration_hours between 1 and 720),
 max_failures integer not null default 3 check(max_failures between 1 and 20),enabled boolean not null default true,
 definition jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(runbook_key,version),
 check(not(risk_class='high_impact' and requires_action_approval=false))
);
create table if not exists public.automation_runbook_steps(
 id uuid primary key default gen_random_uuid(),runbook_id uuid not null references public.automation_runbooks(id) on delete restrict,
 step_key text not null,step_order integer not null check(step_order>0),name text not null,
 action_kind text not null check(action_kind in ('human_task','notify_admin','record_decision')),
 timeout_minutes integer not null default 60 check(timeout_minutes between 1 and 10080),max_attempts integer not null default 1 check(max_attempts between 1 and 10),
 retry_backoff_minutes integer not null default 15 check(retry_backoff_minutes between 1 and 1440),requires_previous_success boolean not null default true,
 payload_template jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(runbook_id,step_key),unique(runbook_id,step_order)
);
create table if not exists public.automation_runbook_instances(
 id uuid primary key default gen_random_uuid(),instance_key text not null unique,runbook_id uuid not null references public.automation_runbooks(id) on delete restrict,
 alert_id uuid not null references public.control_alerts(id) on delete restrict,proposal_id uuid references public.action_proposals(id) on delete restrict,
 status text not null default 'planned' check(status in ('planned','active','paused','completed','failed','cancelled')),
 escalation_level integer not null default 0 check(escalation_level between 0 and 5),failure_count integer not null default 0 check(failure_count>=0),
 source_snapshot jsonb not null default '{}'::jsonb,started_at timestamptz,paused_at timestamptz,completed_at timestamptz,cancelled_at timestamptz,
 deadline_at timestamptz not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create index if not exists automation_instances_queue_idx on public.automation_runbook_instances(status,deadline_at,escalation_level desc);
create table if not exists public.automation_step_runs(
 id uuid primary key default gen_random_uuid(),instance_id uuid not null references public.automation_runbook_instances(id) on delete restrict,
 step_id uuid not null references public.automation_runbook_steps(id) on delete restrict,status text not null default 'pending' check(status in ('pending','ready','running','succeeded','failed','skipped','cancelled')),
 attempt_count integer not null default 0 check(attempt_count>=0),ready_at timestamptz,started_at timestamptz,finished_at timestamptz,next_attempt_at timestamptz,
 last_error text,result jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now(),unique(instance_id,step_id)
);
create table if not exists public.automation_events(
 id bigint generated by default as identity primary key,event_key text not null unique,instance_id uuid not null references public.automation_runbook_instances(id) on delete restrict,
 step_run_id uuid references public.automation_step_runs(id) on delete restrict,event_type text not null,
 actor_id uuid references auth.users(id) on delete set null,metadata jsonb not null default '{}'::jsonb,occurred_at timestamptz not null default now()
);
create table if not exists public.automation_control(
 singleton boolean primary key default true check(singleton),global_paused boolean not null default false,pause_reason text,
 consecutive_failures integer not null default 0 check(consecutive_failures>=0),circuit_open_until timestamptz,updated_at timestamptz not null default now()
);
insert into public.automation_control(singleton) values(true) on conflict(singleton) do nothing;

alter table public.automation_runbooks enable row level security;alter table public.automation_runbook_steps enable row level security;alter table public.automation_runbook_instances enable row level security;alter table public.automation_step_runs enable row level security;alter table public.automation_events enable row level security;alter table public.automation_control enable row level security;
revoke all on public.automation_runbooks,public.automation_runbook_steps,public.automation_runbook_instances,public.automation_step_runs,public.automation_events,public.automation_control from public,anon,authenticated;
grant select,insert,update on public.automation_runbooks,public.automation_runbook_instances,public.automation_step_runs,public.automation_control to service_role;
grant select,insert on public.automation_runbook_steps,public.automation_events to service_role;
comment on table public.automation_runbook_instances is 'V15 governed multi-step automation state. Initial release may mutate only control-plane records.';
